 nyc:{panes:[[110,185],[196,285],[305,640],[660,748],[758,830]],top:190,bottom:907,sky:350,bars:[[279,290],[470,484]]},
 saopaulo:{panes:[[200,438],[449,662],[675,790]],top:292,bottom:900,sky:355},
 london:{panes:[[190,259],[277,460],[478,664],[682,789]],top:385,bottom:922,sky:475,bars:[[786,799]]},
 paris:{panes:[[255,743]],top:215,bottom:740,sky:350},
 rome:{panes:[[366,565],[581,648],[761,790]],top:340,bottom:870,sky:445,bars:[[791,806]]},
